/// PaneInfo describes one pane for pane.list / pane.get. Pane is the internal id
/// used to address the pane in every other command; Handle is its human public
/// label ("w1:p3"). Focused marks the pane focused within its own tab (each tab
/// has one); Visible marks the panes in the current viewport.
///
/// The session knows only the first five fields; the trailing PaneMeta block is
/// runtime-side state (detected agent, live title/cwd) filled in by the
/// dispatcher from Backend.PaneMeta, so automation clients (e.g. cats-todo's
/// drop-target picker) can find agent panes and show where they live without a
/// second protocol.
class PaneInfo {
  const PaneInfo({
    required this.pane,
    this.handle = '',
    this.name = '',
    required this.focused,
    required this.visible,
    this.agent = '',
    this.agentState = '',
    this.agentModel = '',
    this.title = '',
    this.cwd = '',
    this.host = '',
  });

  final int pane;
  final String handle;

  /// custom name; empty if auto-named
  final String name;
  final bool focused;
  final bool visible;

  /// detected agent label ("claude", "codex", …)
  final String agent;

  /// agent activity state ("working", "idle", …); only when Agent is set
  final String agentState;

  /// LLM the agent is running under; only some agents resolve one
  final String agentModel;

  /// live terminal title
  final String title;

  /// live working directory
  final String cwd;

  /// Host is the cathost the pane's terminal lives on, resolved against the
  /// live roster — so it always names a host that exists, including for a pane
  /// restored onto one that has since gone away. It sits here rather than
  /// beside the session's own fields because the resolution is the runtime's:
  /// the model stores an id that may be empty or stale, the backend knows which
  /// machine is actually holding the PTY.
  final String host;

  /// The embedded `PaneMeta` block, regrouped. Go's embedding flattens these
  /// onto the wire; this hands them back as the unit they were declared as.
  PaneMeta get paneMeta => PaneMeta(
        agent: agent,
        agentState: agentState,
        agentModel: agentModel,
        title: title,
        cwd: cwd,
        host: host,
      );

  factory PaneInfo.fromJson(Map<String, Object?> j) => PaneInfo(
        pane: asInt(j['pane']),
        handle: asString(j['handle']),
        name: asString(j['name']),
        focused: asBool(j['focused']),
        visible: asBool(j['visible']),
        agent: asString(j['agent']),
        agentState: asString(j['agent_state']),
        agentModel: asString(j['agent_model']),
        title: asString(j['title']),
        cwd: asString(j['cwd']),
        host: asString(j['host']),
      );

  Map<String, Object?> toJson() => {
        'pane': pane,
        if (handle.isNotEmpty) 'handle': handle,
        if (name.isNotEmpty) 'name': name,
        'focused': focused,
        'visible': visible,
        if (agent.isNotEmpty) 'agent': agent,
        if (agentState.isNotEmpty) 'agent_state': agentState,
        if (agentModel.isNotEmpty) 'agent_model': agentModel,
        if (title.isNotEmpty) 'title': title,
        if (cwd.isNotEmpty) 'cwd': cwd,
        if (host.isNotEmpty) 'host': host,
      };
}

