/// PluginInfo describes one installed plugin for plugin.list. Broken carries the
/// manifest load/validate error for an entry that exists on disk but cannot run
/// (the manifest fields are then empty apart from ID). Env is the identity
/// environment a launch must carry (CATS_PLUGIN_ID / CATS_PLUGIN_DIR) — included
/// per plugin so the front-end composes tab.create params without hard-coding
/// the env var names.
class PluginInfo {
  const PluginInfo({
    required this.id,
    this.name = '',
    this.version = '',
    this.description = '',
    this.linked = false,
    required this.dir,
    this.source = '',
    this.ref = '',
    this.broken = '',
    this.actions = const <PluginActionInfo>[],
    this.env = const <String, String>{},
  });

  final String id;
  final String name;
  final String version;
  final String description;
  final bool linked;
  final String dir;
  final String source;
  final String ref;
  final String broken;
  final List<PluginActionInfo> actions;
  final Map<String, String> env;

  factory PluginInfo.fromJson(Map<String, Object?> j) => PluginInfo(
        id: asString(j['id']),
        name: asString(j['name']),
        version: asString(j['version']),
        description: asString(j['description']),
        linked: asBool(j['linked']),
        dir: asString(j['dir']),
        source: asString(j['source']),
        ref: asString(j['ref']),
        broken: asString(j['broken']),
        actions: asList(j['actions'], (e) => PluginActionInfo.fromJson(asObj(e))),
        env: asMap(j['env'], asString),
      );

  Map<String, Object?> toJson() => {
        'id': id,
        if (name.isNotEmpty) 'name': name,
        if (version.isNotEmpty) 'version': version,
        if (description.isNotEmpty) 'description': description,
        if (linked) 'linked': linked,
        'dir': dir,
        if (source.isNotEmpty) 'source': source,
        if (ref.isNotEmpty) 'ref': ref,
        if (broken.isNotEmpty) 'broken': broken,
        if (actions.isNotEmpty) 'actions': [for (final e in actions) e.toJson()],
        if (env.isNotEmpty) 'env': env,
      };
}

/// PluginListResult is CmdResult.Data for plugin.list. Catctl is the server's
/// best resolution of the catctl binary (PATH first, then a sibling of the
/// server executable) — the dialog spawns `catctl plugin install/update` tabs
/// and the browser has no way to resolve host paths itself.
class PluginListResult {
  const PluginListResult({
    required this.catctl,
    required this.plugins,
  });

  final String catctl;
  final List<PluginInfo> plugins;

  factory PluginListResult.fromJson(Map<String, Object?> j) => PluginListResult(
        catctl: asString(j['catctl']),
        plugins: asList(j['plugins'], (e) => PluginInfo.fromJson(asObj(e))),
      );

  Map<String, Object?> toJson() => {
        'catctl': catctl,
        'plugins': [for (final e in plugins) e.toJson()],
      };
}

