        pane: asInt(j['pane']),
        pattern: asString(j['pattern']),
        regex: asBool(j['regex']),
        timeoutMs: asInt(j['timeout_ms']),
        lines: asInt(j['lines']),
      );

  Map<String, Object?> toJson() => {
        'pane': pane,
        'pattern': pattern,
        if (regex) 'regex': regex,
        if (timeoutMs != 0) 'timeout_ms': timeoutMs,
        if (lines != 0) 'lines': lines,
      };
}

