/// One §7 command as data, mirroring app.CommandSpec.
class CommandSpec {
  const CommandSpec(
    this.name, {
    this.paramsRequired = false,
    this.replyRequired = false,
  });

  final String name;

  /// The command fails with "bad params" when called with none. The rest
  /// decode optionally, where absent params mean the zero value — a
  /// meaningful call (`pane.close` closes the focused pane).
  final bool paramsRequired;

  /// The server SILENTLY DROPS this command when the caller cannot receive a
  /// result — a `cmd` sent with no `id`. It exists only to produce data, so
  /// an answer with nowhere to go is no answer. CatsCommands always sends an
  /// id, so this is a fact about the protocol, not a hazard of this client.
  final bool replyRequired;
}

/// The full vocabulary, in the order `catctl commands` prints it.
const List<CommandSpec> kCommandSpecs = <CommandSpec>[
  CommandSpec('pane.split', paramsRequired: true),
  CommandSpec('pane.close'),
  CommandSpec('pane.focus', paramsRequired: true),
  CommandSpec('pane.focus_direction', paramsRequired: true),
  CommandSpec('pane.cycle', paramsRequired: true),
  CommandSpec('pane.last'),
  CommandSpec('pane.swap', paramsRequired: true),
  CommandSpec('pane.swap_with', paramsRequired: true),
  CommandSpec('pane.zoom'),
  CommandSpec('pane.rename', paramsRequired: true),
  CommandSpec('pane.resize_border', paramsRequired: true),
  CommandSpec('scroll', paramsRequired: true),
